1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	};
9	
10	type Item = {
11	  type: string;
12	  material: string;
13	  enchantmentLevel: number;
14	  cursed: boolean;
15	};
16	
17	type Step = {
18	  op: string;
19	  items: Item[];
20	};
21	
22	type Scenario = {
23	  customer: { yearsWithMHPCO: number };
24	  steps: Step[];
25	};
26	
27	type QuoteResult = {
28	  premium: number;
29	};
30	
31	type ScenarioOutput = {
32	  results: QuoteResult[];
33	};
34	
35	const premiumForItem = (item: Item): number => {
36	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
37	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
38	  return basePremium + firstInsuranceSurcharge;
39	};
40	
41	const premiumForItems = (items: Item[]): number =>
42	  items.reduce((total, item) => total + premiumForItem(item), 0);
43	
44	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
45	  results: scenario.steps.map((step) => ({
46	    premium: premiumForItems(step.items) + PROCESSING_FEE,
47	  })),
48	});
